"""Evidence report for the theme-owned ISO state backport; no invented VM acceptance."""
import collections,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];out=ROOT/'artifacts'
results=[json.loads(line) for line in (ROOT/'build/meson-logs/testlog.json').read_text().splitlines()]
counts=collections.Counter(row['result'] for row in results)
assert counts=={'OK':37},counts
comparison=json.loads((out/'theme-state-backport-comparison.json').read_text())
assert comparison['regular_gtk_css_unchanged'] and comparison['geometry_unchanged']
lines=['# Theme-state backport evidence — 2026-10-11','', 'Baseline: 32/32 passed, preserved in pre-theme-state-backport. Final clean Meson: 37/37 passed, zero skips/failures/timeouts. Generation --check passes.','', '| Contract | Result |','|---|---|', '| GTK3 light/dark desktop active/backdrop | Parsed rules and native zero-alpha background/frame paints PASS; regular backgrounds restore opaque |', '| GTK4 light/dark desktop active/backdrop | Parsed rules and native zero-alpha background/frame paints PASS; regular backgrounds restore opaque |', '| Light Shell | White surfaces, #1C1C1F panel/descendant foregrounds, neutral icon surfaces and #8A8A92 insensitive text/icons PASS |', '| Dark Shell | Panel #202023, transients rgba(40,40,44,.98), search #28282C, #F4F4F5 descendants, #7F7F88 insensitive text/icons PASS |', '| Checked children | #6366F1 backgrounds / #FFFFFF nested foregrounds in both variants PASS |', '| Both Shell source cycles | Independent complete colour ownership; targeted negative regression cases PASS |', '| Development installer | Fixed light/dark, neutral auto, original files/symlinks, migration/conflict protection and restore PASS |', '| Neutral install + GTK4 bridge | Both actual native light/dark cycles PASS |', '| GTK3/GTK4 bridges | Existing implementations unchanged; native variant tests PASS |', '| Application CSS/geometry | Non-desktop declarations unchanged; both full realized geometry reports equal baseline |','', '## Uncropped application comparison','']
for variant in ['light','dark']:
 rows=[r for r in comparison['screenshots'] if r['variant']==variant];changed=[r for r in rows if not r['identical']]
 lines.append(f'{variant.title()}: {len(rows)-len(changed)}/{len(rows)} complete frames pixel-identical.')
 for row in changed:lines.append(f'- {row["file"]}: {row["changed_pixels"]} changed pixels; bounds {row["bbox"]}. Review required; not automatically accepted.')
lines+=['', 'All four header allocations remain 48px; minimize/maximize/restore/close plates 32x32 and glyphs 16x16. Plus Jakarta Sans tests remain required.','', '## Ownership and remaining acceptance','', 'Theme assets and reusable GTK3/GTK4 bridges are supplied here. Global process attachment/dispatcher, Shell extension activation, wallpaper and GNOME/Mutter lifecycle remain distro/session responsibilities. No dispatcher, desktop extension or ISO hook was imported.','', 'GNOME VM validation remains required for actual DING focus/wallpaper/Home/Trash, live St rendering and both Shell switching cycles without logout, late-loading GTK/GJS process attachment, Wayland/Mutter, scaling, portals, Settings and GDM. Native widget constraints are preserved. No full desktop-session conformance claim is made.','', '[17-part completion audit](../docs/theme-state-backport.md) · [Exact changed files](../docs/theme-state-backport-files.txt) · [VM checklist](../docs/theme-state-vm-checklist.md) · [Full comparison](theme-state-backport-comparison.json) · [Desktop probes](desktop-window-probes/) · [Auto bridge](auto-install-bridge.json)','']
(out/'theme-state-backport-report.md').write_text('\n'.join(lines));print('Generated theme-state backport evidence report')
